<section class="dashboard-head"><div class="container"><div class="eyebrow">SYSTEM CONTROL</div><h1>Good overview, <em>better decisions.</em></h1><p>Monitor activity across the PrintPack marketplace.</p></div></section><section class="section-pad"><div class="container"><div class="dashboard-cards"><div class="metric-card"><small>REGISTERED USERS</small><strong><?= $stats['users'] ?></strong><span>All roles</span></div><div class="metric-card"><small>LISTED SERVICES</small><strong><?= $stats['services'] ?></strong><span>Catalogue</span></div><div class="metric-card"><small>ORDERS</small><strong><?= $stats['orders'] ?></strong><span>Across vendors</span></div><div class="metric-card"><small>PENDING VENDORS</small><strong><?= $stats['vendors_pending'] ?></strong><span>Awaiting review</span></div></div><div class="dashboard-section-title"><h2>Vendor approvals</h2></div><div class="orders-table-wrap mb-5"><table class="table align-middle"><thead><tr><th>Vendor</th><th>Email</th><th>Registered</th><th>Action</th></tr></thead><tbody><?php $pending=db()->query("SELECT id,name,email,created_at FROM users WHERE role='vendor' AND status='pending' ORDER BY created_at")->fetchAll(); foreach($pending as $v): ?><tr><td><?= e($v['name']) ?></td><td><?= e($v['email']) ?></td><td><?= e(date('d M Y',strtotime($v['created_at']))) ?></td><td><form method="post" action="<?= e(url('admin/vendor-status')) ?>" class="d-flex gap-2"><?= csrf_field() ?><input type="hidden" name="vendor_id" value="<?= (int)$v['id'] ?>"><button name="status" value="active" class="btn btn-green btn-sm">Approve</button><button name="status" value="rejected" class="btn btn-outline-danger btn-sm">Reject</button></form></td></tr><?php endforeach; ?><?php if(!$pending): ?><tr><td colspan="4" class="text-center py-4">No vendor applications waiting.</td></tr><?php endif; ?></tbody></table></div><div class="dashboard-section-title"><h2>Recent orders</h2><span class="muted-text">Latest 15</span></div><div class="orders-table-wrap"><table class="table align-middle"><thead><tr><th>Order</th><th>Customer</th><th>Vendor</th><th>Total</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td>#<?= (int)$o['id'] ?></td><td><?= e($o['customer_name']) ?></td><td><?= e($o['vendor_name']) ?></td><td><?= money($o['total_amount']) ?></td><td><?= e(ucfirst($o['status'])) ?></td><td><form method="post" action="<?= e(url('orders/status')) ?>" class="d-flex gap-1"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$o['id'] ?>"><select class="form-select form-select-sm" name="status"><?php foreach(['accepted','processing','dispatched','delivered','cancelled'] as $st): ?><option value="<?= $st ?>" <?= $o['status']===$st?'selected':'' ?>><?= ucfirst($st) ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-outline-dark">Go</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></section>
